import hashlib

def blok_karma(onceki, veri):
    return hashlib.sha256((onceki + "|" + veri).encode("utf-8")).hexdigest()

zincir = []
onceki = "0" * 64
for veri in ["parti-A", "parti-B", "parti-C", "parti-D"]:
    h = blok_karma(onceki, veri)
    zincir.append({"onceki": onceki, "veri": veri, "karma": h})
    onceki = h

def dogrula(z):
    for i, b in enumerate(z):
        if blok_karma(b["onceki"], b["veri"]) != b["karma"]:
            return i
        if i > 0 and b["onceki"] != z[i - 1]["karma"]:
            return i
    return -1

print("ilk dogrulama:", dogrula(zincir))
zincir[1]["veri"] = "parti-X"
print("degisiklikten sonra:", dogrula(zincir))
