import hashlib

def ara(veri, zorluk_bit):
    hedef = 1 << (256 - zorluk_bit)
    nonce = 0
    while True:
        h = hashlib.sha256(("%s|%d" % (veri, nonce)).encode("utf-8")).digest()
        if int.from_bytes(h, "big") < hedef:
            return nonce, h.hex()[:8]
        nonce += 1

for bit in [8, 12, 16]:
    n, onek = ara("TEDARIK-blok-7", bit)
    print("zorluk", bit, "nonce", n, "karma", onek, "beklenen", 2 ** bit)

paylar = {"A": 35, "B": 25, "C": 15, "D": 10, "E": 8, "F": 7}

def hhi(p):
    return sum(v * v for v in p.values())

def nakamoto(p, esik):
    sirali = sorted(p.values(), reverse=True)
    toplam, n = 0, 0
    for v in sirali:
        toplam += v
        n += 1
        if toplam > esik:
            return n
    return None

